Implement early withdrawal penalty:

uint256 public constant MIN_STAKE_DURATION = 30 days;

struct StakeInfo {
uint256 amount;
uint256 depositTime;
}

mapping(address => StakeInfo) public stakes;

function withdraw(uint256 amount) external {
updateReward(msg.sender);

StakeInfo storage stake = stakes[msg.sender];
uint256 timeStaked = block.timestamp - stake.depositTime;

// Penalty for early withdrawal (< 30 days)
if (timeStaked < MIN_STAKE_DURATION) {
uint256 rewardAmount = rewards[msg.sender];
uint256 penalty = (rewardAmount * 50) / 100;  // 50% penalty
rewards[msg.sender] -= penalty;

// Redistribute penalty to long-term stakers
totalRewardsTracked += penalty;

emit EarlyWithdrawalPenalty(msg.sender, penalty);
}

stake.amount -= amount;
totalStaked -= amount;
asset.transfer(msg.sender, amount);
}

This prevents farming via quick deposits/withdrawals.

